// Pembantu Carian & Pengurusan Murid UBK SK Tampasuk 1
const MuridHelper = {
  getAll: function() { return SENARAI_MURID; },
  getById: function(id) { return SENARAI_MURID.find(m => m.id === parseInt(id)); },
  getByClass: function(classNameOrCode) {
    const q = (classNameOrCode || '').toUpperCase().trim();
    return SENARAI_MURID.filter(m => m.className.toUpperCase().includes(q) || m.classCode.toUpperCase() === q);
  },
  search: function(query, limit = 25) {
    if (!query) return [];
    const q = query.toLowerCase().trim();
    const cleanQ = q.replace(/[^0-9]/g, '');
    return SENARAI_MURID.filter(m => {
      const matchName = m.name.toLowerCase().includes(q);
      const matchIC = cleanQ.length >= 3 && m.ic.replace(/[^0-9]/g, '').includes(cleanQ);
      const matchClass = m.className.toLowerCase().includes(q) || m.classCode.toLowerCase().includes(q);
      const matchParent = (m.penjaga1 && m.penjaga1.toLowerCase().includes(q)) || (m.penjaga2 && m.penjaga2.toLowerCase().includes(q));
      return matchName || matchIC || matchClass || matchParent;
    }).slice(0, limit);
  },
  getClasses: function() {
    return ['1 ARIF', '1 BESTARI', '2 ARIF', '2 BESTARI', '3 ARIF', '3 BESTARI', '4 ARIF', '4 BESTARI', '5 ARIF', '5 BESTARI', '6 ARIF', '6 BESTARI', 'PRA ANGGERIK', 'PRA DAHLIA'];
  }
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { SENARAI_MURID, MuridHelper };
}
